import csv
import io
import re


def parse_csv(raw_csv: str):
    expected_width = 17

    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=";",
        quotechar='"',
        doublequote=True,
        strict=False,
    )

    records = []
    for row in reader:
        if row:
            records.append(row)

    if not records:
        return {"columns": [], "rows": []}

    def header_score(row):
        nonempty = [value.strip() for value in row if value.strip()]
        if not nonempty:
            return float("-inf")

        width_fit = 1.0 - min(abs(len(row) - expected_width) / expected_width, 1.0)
        alpha_ratio = sum(
            1 for value in nonempty if re.search(r"[A-Za-z]", value)
        ) / len(nonempty)
        return 1.5 * width_fit + 1.2 * alpha_ratio

    candidate_end = min(len(records), 50)
    header_index = max(
        range(candidate_end),
        key=lambda index: (header_score(records[index]), -index),
    )

    columns = list(records[header_index])
    if columns and columns[0].startswith("\ufeff"):
        columns[0] = columns[0].lstrip("\ufeff")

    data_records = records[header_index + 1:]
    width = max(expected_width, len(columns), max((len(row) for row in data_records), default=0))
    columns.extend([""] * (width - len(columns)))

    rows = []
    for record in data_records:
        rows.append(record + [""] * (width - len(record)))

    return {"columns": columns, "rows": rows}
